/** 名称模糊匹配坐标：先全等，再互相包含 */
export function coordOf(name) {
  const raw = String(name || '').trim()
  if (!raw) return null
  if (placeCoord[raw]) return placeCoord[raw]
  const hit = Object.keys(placeCoord).find((k) => raw.includes(k) || k.includes(raw))
  return hit ? placeCoord[hit] : null
}
